  await Q(async db=>{await db.GetService<IMigrator>().MigrateAsync();db.Organizations.Add(new(){Id=org,Name="Advanced settings org"});db.Companies.Add(new(){Id=company,OrganizationId=org,Name="Advanced settings company"});db.Sites.Add(new(){Id=site,CompanyId=company,Name="Advanced settings site",TimeZoneId="UTC"});
   foreach(var(u,n)in new[]{(actor,"settings-owner"),(reader,"settings-reader"),(infoOnly,"settings-info-only"),(service,"settings-service")})db.Users.Add(new(){Id=u,UserName=n,IsActive=true});
   foreach(var(r,u,n,codes)in new[]{(role,actor,"settings-full",new[]{DeviceOperations.ReadSettings,DeviceOperations.Read,DeviceRegistry.Create,DeviceRegistry.Update,DeviceCommands.Read,DeviceCommands.Retry}),(readRole,reader,"settings-read",new[]{DeviceOperations.ReadSettings}),(infoRole,infoOnly,"settings-info",new[]{DeviceOperations.Read,"devices.settings"}),(execRole,service,"settings-exec",new[]{DeviceOperations.Execute})}){
