   await db.SaveChangesAsync();return true;});
  async Task Extra(bool grant){await Q(async db=>{var p=await db.Permissions.SingleOrDefaultAsync(x=>x.Code==DeviceOperations.ExecuteSettings);if(p is null){p=new(){Id=Guid.NewGuid(),Code=DeviceOperations.ExecuteSettings};db.Permissions.Add(p);}if(grant)db.RolePermissions.Add(new(){RoleId=execRole,PermissionId=p.Id});else await db.RolePermissions.Where(x=>x.RoleId==execRole&&x.PermissionId==p.Id).ExecuteDeleteAsync();await db.SaveChangesAsync();return true;});}
  var di=new DeviceRegistry.Input(site,"S11-SETTINGS","Advanced read candidate","unverified SSR","zk-standalone","127.0.0.1",4370,true);await Use<DeviceRegistry,Guid>(s=>s.CreateAsync(actor,device,di));await Use<DeviceRegistry,Guid>(s=>s.CreateAsync(actor,other,di with{Number="S11-SETTINGS-OTHER"}));var dv=await Q(db=>db.Devices.Where(x=>x.Id==device).Select(x=>x.Version).SingleAsync());var ov=await Q(db=>db.Devices.Where(x=>x.Id==other).Select(x=>x.Version).SingleAsync());
  Task<Guid> Request(Guid id,Guid? user=null,string confirmation="READ-ADVANCED-SETTINGS",int timeout=30)=>Use<DeviceOperations,Guid>(s=>s.RequestAsync(user??actor,id,device,dv,"settings.read",timeout,null,confirmation));
  Task<DeviceOperations.Claim?> Claim(bool include=true)=>Use<DeviceOperations,DeviceOperations.Claim?>(s=>s.ClaimAsync(service,includeSettings:include));
  Task<Guid> Finish(DeviceOperations.Claim c,ZkOperationOutput result)=>Use<DeviceOperations,Guid>(s=>s.CompleteAsync(service,c.Id,c.Token,result));
  Task<byte[]> V(Guid id)=>Q(db=>db.DeviceOperations.Where(x=>x.Id==id).Select(x=>x.Version).SingleAsync());
