  check(await Reject<ArgumentException>(()=>Request(Guid.NewGuid(),confirmation:"guess"))&&await Reject<ArgumentException>(()=>Request(Guid.NewGuid(),timeout:61))&&await Reject<ArgumentException>(()=>Use<DeviceOperations,Guid>(s=>s.RequestAsync(actor,Guid.NewGuid(),device,dv,"settings.read",30,clock.GetUtcNow(),"READ-ADVANCED-SETTINGS"))),"S11 settings requests require explicit read confirmation bounded deadline and no clock or arbitrary write target");
  var id=Guid.NewGuid();await Request(id);check(await Request(id)==id&&await Reject<DomainConflictException>(()=>Request(id,timeout:31))&&await Reject<DomainConflictException>(()=>Request(Guid.NewGuid())),"S11 settings exact request replay is idempotent while changed payload and concurrent same-device work are rejected");
  check(await Claim(false)==null&&await Claim()==null,"S11 ordinary operation execution cannot dispatch advanced settings without both opt-in and the additional service grant");
