  check(infoClaim.Id==info&&await Reject<ArgumentException>(()=>Finish(infoClaim,new("succeeded",Settings:snapshot))),"S11 an unapproved settings queue does not starve independent information reads and snapshot kinds cannot be mixed");await Finish(infoClaim,new("failed"));
  await Extra(true);check(await Claim(false)==null,"S11 the extra settings execution grant alone cannot bypass explicit scheduler inclusion");var c=await Claim()??throw new InvalidOperationException();
  await Extra(false);check(await Reject<UnauthorizedAccessException>(()=>Finish(c,new("succeeded",Settings:snapshot)))&&await Reject<UnauthorizedAccessException>(()=>Use<DeviceOperations,DeviceCommunicationKey?>(s=>s.CredentialAsync(service,c,true))),"S11 service grant revocation blocks owned settings completion and private credential access before any key is exposed");await Extra(true);
  check(await Reject<ArgumentException>(()=>Finish(c,new("succeeded")))&&await Reject<ArgumentException>(()=>Finish(c,new("succeeded",Settings:snapshot with{Contract="unversioned"})))&&await Reject<ArgumentException>(()=>Finish(c,new("failed",Settings:snapshot))),"S11 settings success needs a valid versioned typed snapshot and failed outcomes cannot carry an invented success payload");
  await Finish(c,new("succeeded",Settings:snapshot));var json=JsonSerializer.SerializeToElement(await Use<DeviceOperations,object>(s=>s.ListSettingsAsync(reader,device,0)),new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase});var saved=json.GetProperty("items")[0].GetProperty("settings");var ordinary=JsonSerializer.SerializeToElement(await Use<DeviceOperations,object>(s=>s.ListAsync(actor,device,0)));
  check(saved.GetProperty("oneToOne").GetInt32()==0&&saved.GetProperty("oneToN").ValueKind==JsonValueKind.Null&&saved.GetProperty("repeatTime").GetInt32()==int.MinValue&&saved.GetProperty("sleepTime").GetInt32()==int.MaxValue&&saved.GetProperty("regCard").GetInt32()==2&&ordinary.GetProperty("items").GetArrayLength()==0,"S11 SQL snapshots preserve zero unavailable signed raw settings and non-boolean values while ordinary information history never exposes them");
  var pending=Guid.NewGuid();await Request(pending);var version=await V(pending);await Use<DeviceOperations,Guid>(s=>s.CancelAsync(reader,pending,version));check(await Reject<DomainConflictException>(()=>Use<DeviceOperations,Guid>(s=>s.CancelAsync(reader,pending,version)))&&await Claim()==null,"S11 advanced read cancellation is versioned and prevents dispatch only while pending");
  var revoked=Guid.NewGuid();await Request(revoked,reader);await Q(db=>db.RolePermissions.Where(x=>x.RoleId==readRole).ExecuteDeleteAsync());check(await Claim()==null&&await Q(db=>db.DeviceOperations.AnyAsync(x=>x.Id==revoked&&x.State=="revoked"))&&await Reject<UnauthorizedAccessException>(()=>Use<DeviceOperations,object>(s=>s.ListSettingsAsync(reader,device,0))),"S11 human settings grant revocation removes retained snapshots and prevents queued dispatch on the existing actor");
  var crash=Guid.NewGuid();await Request(crash);c=await Claim()??throw new InvalidOperationException();clock.Advance(TimeSpan.FromMinutes(3));check(await Claim()==null&&await Q(db=>db.DeviceOperations.AnyAsync(x=>x.Id==crash&&x.State=="interrupted"))&&await Reject<DomainConflictException>(()=>Finish(c,new("succeeded",Settings:snapshot))),"S11 abandoned settings reads become interrupted with retained history no automatic replay and no accepted late completion");
  var retry=new DeviceCommands.RetryInput(Guid.NewGuid(),"operation",crash,await V(crash),dv,"RETRY-READ-ONLY-COMMAND");check(await Reject<DomainConflictException>(()=>Use<DeviceCommands,Guid>(s=>s.RetryAsync(actor,retry))),"S11 advanced settings generic retry requires its additional explicit typed read consent");
  var approvedRetry=retry with{SettingsConfirmation="READ-ADVANCED-SETTINGS"};
  await Q(db=>db.RolePermissions.Where(x=>x.RoleId==role&&x.PermissionId==db.Permissions.Where(p=>p.Code==DeviceOperations.ReadSettings).Select(p=>p.Id).Single()).ExecuteDeleteAsync());
  check(await Reject<UnauthorizedAccessException>(()=>Use<DeviceCommands,Guid>(s=>s.RetryAsync(actor,approvedRetry))),"S11 settings retry also requires the current independent settings read grant rather than information read or generic retry alone");
  await Q(async db=>{db.RolePermissions.Add(new(){RoleId=role,PermissionId=await db.Permissions.Where(p=>p.Code==DeviceOperations.ReadSettings).Select(p=>p.Id).SingleAsync()});await db.SaveChangesAsync();return true;});
  var settingsChild=await Use<DeviceCommands,Guid>(s=>s.RetryAsync(actor,approvedRetry));
  check(await Use<DeviceCommands,Guid>(s=>s.RetryAsync(actor,approvedRetry))==settingsChild&&await Q(db=>db.DeviceCommandRetries.AnyAsync(x=>x.PreviousOperationId==crash&&x.NextOperationId==settingsChild))&&await Q(db=>db.DeviceOperations.AnyAsync(x=>x.Id==settingsChild&&x.Kind=="settings.read"&&x.State=="pending"))&&await Q(db=>db.DeviceOperations.AnyAsync(x=>x.Id==crash&&x.State=="interrupted")),"S11 separately confirmed advanced settings retry creates one new typed read and immutable lineage without rewriting interrupted evidence");
  var settingsChildVersion=await V(settingsChild);await Use<DeviceOperations,Guid>(s=>s.CancelAsync(actor,settingsChild,settingsChildVersion));
  var stale=Guid.NewGuid();await Request(stale);await Use<DeviceRegistry,Guid>(s=>s.UpdateAsync(actor,device,dv,di with{Name="Changed advanced read target"}));check(await Claim()==null&&await Q(db=>db.DeviceOperations.AnyAsync(x=>x.Id==stale&&x.State=="device-changed")),"S11 a changed device version fences older settings requests without retargeting their snapshot");
