 private sealed class Clock:TimeProvider{private DateTimeOffset now=DateTimeOffset.UtcNow;public override DateTimeOffset GetUtcNow()=>now;public void Advance(TimeSpan delta)=>now=now.Add(delta);public void Reset()=>now=DateTimeOffset.UtcNow;}
